from collections import deque as d

class Child:
    def __init__(self, cry, leave, cond):
        self.cry = cry
        self.leave = leave
        self.cond = cond
        self.alive = True

N = int(input())

queue = d()
for i in range(N):
    lst = list(map(int, input().split()))
    queue.append(Child(lst[0], lst[1], lst[2]))

ans = []
while queue:
    child = queue.popleft()
    if not child.alive:
        continue
    ans.append(child)
    cry, leave = child.cry, 0
    for _ in range(len(queue)):
        next_child = queue.popleft()
        if next_child.alive:
            next_child.cond -= (cry + leave)
            if next_child.cond < 0:
                next_child.alive = False
                leave += next_child.leave
            if cry:
                cry -= 1
        queue.append(next_child)
        if cry == 0 and leave == 0:
            break

print(len(ans))
print(*[i + 1 for i, child in enumerate(ans)])

