def median_smoothing(sequence):
    n = len(sequence)
    if n <= 2:
        return sequence
    new_sequence = [sequence[0]] + [0] * (n - 2) + [sequence[-1]]
    for i in range(1, n - 1):
        triplet = (sequence[i-1], sequence[i], sequence[i+1])
        count_ones = sum(triplet)
        new_sequence[i] = 1 if count_ones >= 2 else 0
    return new_sequence

def is_stable(sequence):
    return sequence == median_smoothing(sequence)

def find_stable_sequence(sequence):
    n = len(sequence)
    if is_stable(sequence):
        return 0, sequence

    seen_sequences = {}
    current_sequence = sequence
    steps = 0

    while True:
        if tuple(current_sequence) in seen_sequences:
            return -1, []

