def longest_alternating_subsequence(s):
    n = len(s)
    if n == 1:
        return 1

    # Calculate left and right arrays
    left = [0] * n
    right = [0] * n

    # Fill left array
    left[0] = 1
    for i in range(1, n):
        if s[i] != s[i-1]:
            left[i] = left[i-1] + 1
        else:
            left[i] = 1

    # Fill right array
    right[n-1] = 1
    for i in range(n-2, -1, -1):
        if s[i] != s[i+1]:
            right[i] = right[i+1] + 1
        else:
            right[i] = 1

    # Calculate initial LAS
    max_las = max(left)

    # Calculate maximum LAS after flipping any substring
    for i in range(n):
        for j in range(i, n):
            # Calculate new LAS if substring s[i:j+1] is flipped
            if i > 0:
                prev_las = left[i-1]
            else:
                prev_las = 0

            if j < n-1:
                next_las = right[j+1]
            else:
                next_las = 0

            # Calculate new LAS of flipped substring
            if i == 0 or j == n-1 or s[i-1] != s[j+1]:
                new_las = 2
            else:
                new_las = 0

            if i > 0 and j < n-1:
                if s[i-1] == s[j]:
                    new_las += left[i-2] if i-2 >= 0 else 0
                if s[j+1] == s[i]:
                    new_las += right[j+2] if j+2 < n else 0

            max_las = max(max_las, prev_las + new_las + next_las)

    return max_las

