import sys

def main():
    n = int(input())
    s = sys.stdin.readline().strip()

    # Calculate the initial longest alternating subsequence
    initial_length = 1
    for i in range(1, n):
        if s[i] != s[i - 1]:
            initial_length += 1

    # Function to calculate the length of the longest alternating subsequence after flipping a substring
    def calculate_length_after_flip(start, end):
        length = 0
        if start > 0 and s[start - 1] != s[end]:
            length += 1
        if end < n - 1 and s[start] != s[end + 1]:
            length += 1
        for i in range(start, end + 1):
            if i == start or s[i] != s[i - 1]:
                length += 1
        return length

    max_length = initial_length
    for i in range(n):
        for j in range(i, n):
            # Flip the substring s[i:j+1]
            flipped_s = s[:i] + ('1' if s[i] == '0' else '0') * (j - i + 1) + s[j + 1:]
            # Calculate the new length of the longest alternating subsequence
            new_length = 1
            for k in range(1, n):
                if flipped_s[k] != flipped_s[k - 1]:
                    new_length += 1
            max_length = max(max_length, new_length)

    print(max_length)

