def min_days(required_experience, required_money, projects):
    max_experience = max(a for a, b in projects)
    max_money = max(b for a, b in projects)
    projects.sort(key=lambda t: (t[0], -t[1]))

    # Construct the convex hull
    convex_hull = [(0, max_money)]
    for a, b in projects:
        if a == convex_hull[-1][0]:
            continue
        while (
            len(convex_hull) >= 2
            and ((b - convex_hull[-2][1]) * (convex_hull[-1][0] - convex_hull[-2][0])
                 >= (a - convex_hull[-2][0]) * (convex_hull[-1][1] - convex_hull[-2][1]))
        ):
            convex_hull.pop()
        convex_hull.append((a, b))
    convex_hull.append((max_experience, 0))

    prev_experience, prev_money = None, None
    for current_experience, current_money in convex_hull:
        if prev_experience is not None:
            delta_experience = current_experience - prev_experience
            delta_money = prev_money - current_money
            if delta_experience * required_money + delta_money * required_experience > 0:
