def hadamard_matrix(k):
    if k == 0:
        return [[1]]
    H_prev = hadamard_matrix(k - 1)
    n = len(H_prev)
    H = [[0] * (2 * n) for _ in range(2 * n)]
    for i in range(n):
        for j in range(n):
            H[i][j] = H_prev[i][j]
            H[i][j + n] = H_prev[i][j]
            H[i + n][j] = H_prev[i][j]
            H[i + n][j + n] = -H_prev[i][j]
    return H

def format_hadamard_matrix(H):
    n = len(H)
    result = []
    for row in H:
        formatted_row = ''.join('+' if x == 1 else '*' for x in row)
        result.append(formatted_row)
    return result

