import math

def main():
    n, xp, yp = map(int, input().split())
    polygon = [tuple(map(int, input().split())) for _ in range(n)]
    print(solver((xp, yp), polygon))

def solver(P, polygon):
    xp, yp = P
    distances = [math.dist(P, vertex) for vertex in polygon]
    maxDist = max(distances)
    minDist = min(distances)
    for i in range(len(polygon)):
        p = perpenPoint(polygon[i], polygon[(i + 1) % len(polygon)], P)
        if p is not None:
            minDist = min(minDist, math.dist(P, p))
    area = math.pi * (maxDist**2 - minDist**2)
    return area

def toLine(point1, point2):
    x1, y1 = point1
    x2, y2 = point2
    if x1 == x2:
        return (1, 0, x1)
    else:
        a = (y2 - y1) / (x1 - x2)
        c = a * x1 + y1
        return (a, 1, c)

def perpenPoint(point1, point2, point):
    a, b, c = toLine(point1, point2)
    if a == 0:
        ap, bp = b, a
    else:
        ap, bp = -1 / a, 1
    x, y = point
    cp = ap * x + bp * y
    xi, yi = intersection((a, b, c), (ap, bp, cp))
    x1, y1 = point1
    x2, y2 = point2
    if min(x1, x2) <= xi <= max(x1, x2) and min(y1, y2) <= yi <= max(y1, y2):
        return (xi, yi)
