from math import sqrt

def level(n):
    if n == 0:
        return 0, 0
    l = int((-3 + sqrt(9 + 12 * (n - 1))) / 6)
    k = n - 1 - 3 * l * (l + 1) // 2
    return l + 1, k

def coordinates(l, k):
    if l == 0:
        return 0, 0
    s, i = divmod(k, l)
    if s == 0:
        return 2 * l - (i + 1), 2 * (i + 1)
    elif s == 1:
