import math

def distance(x1, y1, x2, y2):
    return math.sqrt((x1 - x2) ** 2 + (y1 - y2) ** 2)

def can_cover(flowers, x1, y1, x2, y2, r1, r2):
    for x, y in flowers:
        if distance(x, y, x1, y1) <= r1 or distance(x, y, x2, y2) <= r2:
            continue
        else:
            return False
    return True

def min_r_squared(n, x1, y1, x2, y2, flowers):
    low = 0
    high = 10**14  # A large enough upper bound
    best_r_squared = high

    while low <= high:
        mid_r_squared = (low + high) // 2
        found = False

        for r1_squared in range(mid_r_squared + 1):
            r2_squared = mid_r_squared - r1_squared
            r1 = int(math.sqrt(r1_squared))
            r2 = int(math.sqrt(r2_squared))

            if can_cover(flowers, x1, y1, x2, y2, r1, r2):
                found = True
                break

        if found:
            best_r_squared = mid_r_squared
            high = mid_r_squared - 1
        else:
            low = mid_r_squared + 1

    return best_r_squared

