from collections import defaultdict, deque

def can_form_string(n, edges):
    # Create adjacency list
    adj_list = defaultdict(list)
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    # Initialize character assignments
    chars = [''] * (n + 1)

    def bfs(start):
        queue = deque([start])
        chars[start] = 'a'
        while queue:
            current = queue.popleft()
            current_char = chars[current]
            for neighbor in adj_list[current]:
                if chars[neighbor] == '':
                    # Assign a valid character to the neighbor
                    if current_char == 'a':
                        chars[neighbor] = 'b'
                    elif current_char == 'b':
                        chars[neighbor] = 'c'
                    else:  # current_char == 'c'
                        chars[neighbor] = 'a'
                    queue.append(neighbor)
                else:
                    # Check if the neighbor's character is valid
                    if abs(ord(current_char) - ord(chars[neighbor])) != 1:
                        return False
        return True

    # Perform BFS for each component
    for i in range(1, n + 1):
        if chars[i] == '':
            if not bfs(i):
                return "No"

    # Validate the entire graph
    for u, v in edges:
        if abs(ord(chars[u]) - ord(chars[v])) not in [0, 1]:
            return "No"

    # If all checks pass, return the string
    return "Yes\n" + ''.join(chars[1:])

