def kmp_table(pattern):
    n = len(pattern)
    table = [0] * n
    j = 0
    for i in range(1, n):
        while (j > 0 and pattern[i] != pattern[j]):
            j = table[j - 1]
        if pattern[i] == pattern[j]:
            j += 1
        table[i] = j
    return table

def kmp_search(text, pattern):
    m, n = len(text), len(pattern)
    table = kmp_table(pattern)
    j = 0
    matches = []
    for i in range(m):
        while (j > 0 and text[i] != pattern[j]):
            j = table[j - 1]
        if text[i] == pattern[j]:
            j += 1
        if j == n:
            matches.append(i - n + 1)
            j = table[j - 1]
    return matches

def min_replacements(text, pattern):
    matches = kmp_search(text, pattern)
    if not matches:
        return 0

    n = len(matches)
    dp = [0] * n
    dp[0] = len(pattern)

    for i in range(1, n):
        if matches[i] < matches[i - 1] + len(pattern):
            dp[i] = min(dp[i - 1], dp[i - 1] + matches[i] - matches[i - 1])
        else:
            dp[i] = dp[i - 1] + len(pattern)

    return dp[-1] // len(pattern)

