def count_ways(n):
    if n == 3:
        return 24

    # Number of ways to arrange n-2 cars of 3 makes such that no block of n successive cars of the same make
    def count_valid_sequences(length, last_char, last_count):
        if length == 0:
            return 1
        count = 0
        for char in 'ABMZ':
            if char != last_char:
                count += count_valid_sequences(length - 1, char, 1)
            elif last_count < n - 1:
                count += count_valid_sequences(length - 1, char, last_count + 1)
        return count

    # Total ways to place the block of n successive cars and arrange the remaining cars
    total_ways = 0
    for start in range(n):
        total_ways += count_valid_sequences(n - 2, '', 0)

    return 4 * total_ways

