def inclusion_exclusion(n, divisors):
    total = 0
    num_divisors = len(divisors)
    for i in range(1, 1 << num_divisors):
        count = 0
        lcm = 1
        for j in range(num_divisors):
            if i & (1 << j):
                count += 1
                lcm = lcm * divisors[j] // gcd(lcm, divisors[j])
        if count % 2 == 1:
            total -= n // lcm
        else:
            total += n // lcm
    return total

