def kmp_search(text_blocks, pattern_blocks):
    if not pattern_blocks:
        return 0

    # Precompute the prefix array for the pattern
    prefix = [0] * len(pattern_blocks)
    j = 0
    for i in range(1, len(pattern_blocks)):
        while j > 0 and not match(pattern_blocks[j], pattern_blocks[i]):
            j = prefix[j - 1]
        if match(pattern_blocks[j], pattern_blocks[i]):
            j += 1
        prefix[i] = j

    # Search for the pattern in the text
    count = 0
    j = 0
    for i, text_block in enumerate(text_blocks):
        while j > 0 and not match(pattern_blocks[j], text_block):
            j = prefix[j - 1]
        if match(pattern_blocks[j], text_block):
            j += 1
        if j == len(pattern_blocks):
            # Check the full match including the boundaries
            if (i - j + 1 >= 0 and 
                match(text_blocks[i - j + 1], pattern_blocks[0]) and 
                match(text_blocks[i], pattern_blocks[-1])):
                count += 1
            j = prefix[j - 1]

    return count

