    min_distance = float("inf")
    j = 0

    for i in range(n):
        if s[i] == "1":
            continue

        count = 0
        left = i - 1
        right = i + 1

        while count < k + 1:
            if left >= 0 and s[left] == "0":
                count += 1
                left -= 1
            if count < k + 1 and right < n and s[right] == "0":
                count += 1
                right += 1

            if count == k + 1:
