def floyd_warshall(n, dist):
    # Apply Floyd-Warshall algorithm
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # Find the maximum shortest path length
    max_shortest_path = 0
    for i in range(n):
        for j in range(n):
            if i != j and dist[i][j] > max_shortest_path:
                max_shortest_path = dist[i][j]

    return max_shortest_path

