def solve_rebus(rebus):
    parts = rebus.split()
    lhs = parts[:-2]
    rhs = int(parts[-1])

    # Extract question marks and operators
    questions = []
    operators = []
    for part in lhs:
        if part == '?':
            questions.append(1)  # Initialize with 1
        elif part in '+-':
            operators.append(part)

    # Initial sum of all question marks set to 1
    current_sum = len(questions)

    # Try to adjust the values to match the RHS
    for i in range(len(questions)):
        if current_sum == rhs:
            break

        max_possible = rhs - (current_sum - questions[i])
        if max_possible <= 0:
            return "Impossible"

        if operators[i] == '+':
            questions[i] = min(n, max_possible)
        else:
            questions[i] = min(n, max_possible)

        current_sum = sum(q if op == '+' else -q for q, op in zip(questions, operators))

    if current_sum != rhs:
        return "Impossible"

    # Construct the result string
    result = []
    for part in lhs:
        if part == '?':
            result.append(str(questions.pop(0)))
        else:
            result.append(part)
    result.append('=')
    result.append(str(rhs))

    return "Possible\n" + ' '.join(result)

