def min_additional_rod_length(n, rods):
    rods.sort()
    total_sum = sum(rods)

    # Check if the sum of all but the largest rod is greater than the largest rod
    if total_sum - rods[-1] > rods[-1]:
        return 0

    current_sum = 0
    for i in range(n):
        current_sum += rods[i]
        if current_sum > rods[i + 1] if i + 1 < n else float('inf'):
            continue
        else:
            if i == n - 1:
                return total_sum - current_sum + 1
            else:
                return rods[i + 1] - current_sum + 1

