import math

def to_base_7(num, length):
    if num == 0:
        return '0' * length
    digits = []
    while num:
        digits.append(int(num % 7))
        num //= 7
    return ''.join(str(x) for x in digits[::-1]).zfill(length)

def count_unique_digit_pairs(n, m):
    d_h = math.ceil(math.log(n, 7)) if n > 1 else 1
    d_m = math.ceil(math.log(m, 7)) if m > 1 else 1

    count = 0
    for hour in range(n):
        hour_str = to_base_7(hour, d_h)
        for minute in range(m):
            minute_str = to_base_7(minute, d_m)
            combined = hour_str + minute_str
            if len(set(combined)) == len(combined):
                count += 1
    return count

