def find_subset_sums(coins, target_sum):
    n = len(coins)
    dp = [[False] * (target_sum + 1) for _ in range(n + 1)]
    dp[0][0] = True

    for i in range(1, n + 1):
        for j in range(target_sum + 1):
            dp[i][j] = dp[i - 1][j]
            if j >= coins[i - 1]:
                dp[i][j] |= dp[i - 1][j - coins[i - 1]]

    subset_sums = []
    for i in range(1 << n):
        subset_sum = 0
        subset = []
        for j in range(n):
            if i & (1 << j):
                subset_sum += coins[j]
                subset.append(coins[j])
        if subset_sum == target_sum:
            subset_sums.append(subset)

    possible_values = set()
    for subset in subset_sums:
        m = len(subset)
        subset_dp = [False] * (target_sum + 1)
        subset_dp[0] = True
        for num in subset:
            for j in range(target_sum, num - 1, -1):
                if subset_dp[j - num]:
                    subset_dp[j] = True
        for j in range(1, target_sum + 1):
            if subset_dp[j]:
                possible_values.add(j)

    return sorted(possible_values)

