def brain_latency(n, m, connections):
    # Initialize the distance matrix with infinity
    dist = [[float('inf')] * n for _ in range(n)]

    # Distance from a brain to itself is 0
    for i in range(n):
        dist[i][i] = 0

    # Set the distance between directly connected brains to 1
    for a, b in connections:
        dist[a-1][b-1] = 1
        dist[b-1][a-1] = 1

    # Floyd-Warshall algorithm to find shortest paths between all pairs of brains
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # Find the maximum shortest path length (brain latency)
    max_distance = 0
    for i in range(n):
        for j in range(i + 1, n):
            max_distance = max(max_distance, dist[i][j])

    return max_distance

