    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def fix_tree(n, a):
    parent = list(range(n + 1))
    rank = [0] * (n + 1)
    changes = 0
    root_candidates = set()

    for i in range(1, n + 1):
        if a[i - 1] == i:
            root_candidates.add(i)
        else:
            root = find(parent, a[i - 1])
            if root == i:
                changes += 1
                # Arbitrarily choose a new parent for i
                new_parent = 1 if 1 not in root_candidates else 2
                a[i - 1] = new_parent
                union(parent, rank, i, new_parent)
            else:
                union(parent, rank, i, root)

