import math
from math import gcd

def find_pythagorean_triple(n):
    # Check if n is the hypotenuse
    for r in range(1, int(math.sqrt(n)) + 1):
        s_squared = n - r * r
        if s_squared > 0:
            s = int(math.sqrt(s_squared))
            if s * s == s_squared and gcd(r, s) == 1 and (r % 2 != s % 2):
                m = r * r - s * s
                k = 2 * r * s
                return m, k

    # Check if n is one of the legs
    for m in range(1, 10**9 + 1):
        k_squared = n * n + m * m
        k = int(math.sqrt(k_squared))
        if k * k == k_squared:
            return m, k

    return -1

