    num_str = bin(num)[2:][::-1]
    pattern_str = pattern[::-1]
    for i in range(max(len(num_str), len(pattern_str))):
        if i >= len(num_str) and pattern_str[i] == '1':
            return False
        if i >= len(pattern_str) and num_str[i] in '13579':
            return False
        if i < len(num_str) and i < len(pattern_str):
            if pattern_str[i] == '0' and num_str[i] in '13579':
                return False
            if pattern_str[i] == '1' and num_str[i] in '02468':
                return False
    return True

def process_queries(queries):
    from collections import defaultdict

    multiset = defaultdict(int)
    results = []

    for query in queries:
        parts = query.split()
        if parts[0] == '+':
            num = int(parts[1])
            multiset[num] += 1
        elif parts[0] == '-':
            num = int(parts[1])
            multiset[num] -= 1
        elif parts[0] == '?':
            pattern = parts[1]
            count = 0
            for num, cnt in multiset.items():
                if match_pattern(num, pattern):
                    count += cnt
            results.append(count)

    return results

