def complete_the_word(s):
    from collections import Counter

    if len(s) < 26:
        return -1

    alphabet = set('ABCDEFGHIJKLMNOPQRSTUVWXYZ')

    def can_form_pangram(count, num_question_marks):
        # Check if we can form a pangram with the current counts and question marks
        missing_letters = alphabet - {char for char, cnt in count.items() if cnt > 0}
        return len(missing_letters) <= num_question_marks

    for i in range(len(s) - 25):
        window = s[i:i+26]
        count = Counter(window)
        num_question_marks = count['?']

        if can_form_pangram(count, num_question_marks):
            # Form the valid substring
            missing_letters = list(alphabet - {char for char, cnt in count.items() if cnt > 0})
            result = list(window)

            # Replace question marks with missing letters
            j = 0
            for k in range(26):
                if result[k] == '?':
                    result[k] = missing_letters[j]
                    j += 1

            # Construct the full result
            full_result = list(s[:i]) + result + list(s[i+26:])

            # Replace remaining question marks with 'A'
            for k in range(len(full_result)):
                if full_result[k] == '?':
                    full_result[k] = 'A'

            return ''.join(full_result)

    return -1

