from string import ascii_uppercase as ALPHABET

def complete_word(word):
    for start_index in range(len(word) - 25):
        substring = word[start_index:start_index + 26]
        missing_letters = set(ALPHABET) - set(substring.replace('?', ''))
        if len(missing_letters) == substring.count('?'):
            result = list(substring)
            for letter in missing_letters:
                result[result.index('?')] = letter
            return ''.join(result) + word[start_index + 26:]
    return '-1'

print(complete_word(input()))

