def car_repair_schedule(n, requests):
    # Dictionary to keep track of the end day for each start day
    schedule = {}

    results = []

    for si, di in requests:
        # Check if the preferred start day and the next di-1 days are available
        available = True
        for day in range(si, si + di):
            if day in schedule:
                available = False
                break

        if available:
            # Mark these days as occupied
            for day in range(si, si + di):
                schedule[day] = si + di - 1
            results.append((si, si + di - 1))
        else:
            # Find the earliest day x such that x through x + di - 1 are all available
            x = 1
            while True:
                available = True
                for day in range(x, x + di):
                    if day in schedule:
                        available = False
                        x = schedule[day] + 1
                        break
                if available:
                    # Mark these days as occupied
                    for day in range(x, x + di):
                        schedule[day] = x + di - 1
                    results.append((x, x + di - 1))
                    break

    return results

