import math

def find_cycles(n, crush):
    visited = [False] * n
    in_stack = [False] * n
    stack = []
    parent = [-1] * n
    cycles = []

    def dfs(node):
        visited[node] = True
        in_stack[node] = True
        stack.append(node)

        next_node = crush[node] - 1
        if visited[next_node]:
            if in_stack[next_node]:
                cycle = []
                while stack[-1] != next_node:
                    cycle.append(stack.pop())
                cycle.append(stack.pop())
                cycles.append(cycle[::-1])
        else:
            parent[next_node] = node
            dfs(next_node)

        stack.pop()
        in_stack[node] = False

    for i in range(n):
        if not visited[i]:
            dfs(i)

    return cycles

def lcm_of_list(lst):
    return math.lcm(*lst)

def find_min_t(n, crush):
    cycles = find_cycles(n, crush)
    if not cycles:
        return -1

    cycle_lengths = [len(cycle) for cycle in cycles]
    min_t = lcm_of_list(cycle_lengths)

    return min_t

