def check_journey(n, instructions):
    # Constants
    NORTH_POLE = 0
    SOUTH_POLE = 20000

    # Initial position
    latitude = NORTH_POLE

    # Process each instruction
    for t, direction in instructions:
        if latitude == NORTH_POLE:
            if direction != "South":
                return "NO"
        elif latitude == SOUTH_POLE:
            if direction != "North":
                return "NO"

        # Update latitude based on direction
        if direction == "North":
            latitude -= t
        elif direction == "South":
            latitude += t
        # East and West do not change latitude

        # Ensure latitude stays within bounds
        if latitude < NORTH_POLE or latitude > SOUTH_POLE:
            return "NO"

    # Final position check
    if latitude == NORTH_POLE:
        return "YES"
    else:
        return "NO"

