def parse_message(message):
    if ':' in message:
        sender, text = message.split(':', 1)
        return sender, text
    else:
        return None, message

def can_send(sender, text, users):
    # Check if the sender mentions themselves in the text
    words = text.split()
    for word in words:
        if word == sender:
            return False
    return True

def recover_senders(chat):
    n = int(input().strip())
    users = set(input().strip().split())
    m = int(input().strip())
    messages = [parse_message(input().strip()) for _ in range(m)]

    available_users = users.copy()
    last_sender = None

    for i, (sender, text) in enumerate(messages):
        if sender is not None:
            if last_sender == sender or not can_send(sender, text, users):
                return "Impossible"
            last_sender = sender
            available_users.discard(sender)
        else:
            valid_senders = [user for user in available_users if can_send(user, text, users)]
            if not valid_senders:
                return "Impossible"
            sender = valid_senders[0]
            last_sender = sender
            available_users.discard(sender)
            available_users.add(last_sender)  # Add back the last sender for future messages

        messages[i] = (sender, text)

    return '\n'.join(f"{sender}:{text}" for sender, text in messages)

