    if n == 1:
        max_questions = (k + m - 1) // m
        min_questions = max_questions if k % m == 0 else max_questions - 1
        sergi_questions = (k + y - 1) // m
        return max_questions, min_questions, sergi_questions

    full_cycle_rows = 2 * (n - 1) + 1
    full_cycle_students = m * full_cycle_rows
    full_cycles = k // full_cycle_students
    remaining_questions = k % full_cycle_students

    max_questions = full_cycles * m
    min_questions = full_cycles * m

    # Determine the number of times each row is asked in the remaining questions
    remaining_rows = 0
    i = 1
    while remaining_questions > 0:
        if i <= n:
            remaining_questions -= m
            remaining_rows += 1
        else:
            remaining_questions -= m
            remaining_rows -= 1
        i += 1

    if remaining_rows >= n:
        max_questions += m
    elif remaining_rows > 0:
        max_questions += remaining_rows

    if remaining_rows <= 2:
        min_questions += remaining_rows
    else:
