    n, m = len(a), len(b)
    longest_start = 0
    longest_end = 0
    max_length = 0

    # Find the longest subsequence from the start
    j = 0
    for i in range(n):
        if j < m and a[i] == b[j]:
            j += 1
    longest_start = j

    # Find the longest subsequence from the end
    j = m - 1
    for i in range(n - 1, -1, -1):
        if j >= 0 and a[i] == b[j]:
            j -= 1
    longest_end = m - 1 - j

    # Check if we can combine both subsequences
    if longest_start + longest_end >= m:
        return b

    # Use two pointers to find the longest subsequence
    start = 0
    end = m - 1
    while start <= end:
        if a.find(b[start], start) != -1:
            start += 1
        elif a.rfind(b[end], 0, n - (m - end)) != -1:
            end -= 1
        else:
