    left = [K] * K
    right = [K] * K
    mid = K // 2 + 1
    return left, right, mid

def calculate_distance(size, row, mid, start):
    return size * abs(row - mid) + sum(abs(i - mid) for i in range(start, start + size))

def find_best_space(left, right, K, mid, size):
    min_result = float('inf')
    best_row = -1
    best_start = -1
    best_side = -1

    for j in range(mid):
        for side in range(2):
            if side == 0:  # Left side
                if left[mid - j - 1] >= size:
                    start = left[mid - j - 1] - size + 1
                    distance = calculate_distance(size, mid - j, mid, start)
                    if distance < min_result:
                        min_result = distance
                        best_row = mid - j
                        best_start = start
                        best_side = side
            else:  # Right side
                if right[mid - j - 1] >= size:
                    start = K - right[mid - j - 1] + 1
                    distance = calculate_distance(size, mid - j, mid, start)
                    if distance < min_result:
                        min_result = distance
                        best_row = mid - j
                        best_start = start
                        best_side = side

    for j in range(1, mid + 1):
        for side in range(2):
            if side == 0:  # Left side
                if left[mid + j - 1] >= size:
                    start = left[mid + j - 1] - size + 1
                    distance = calculate_distance(size, mid + j, mid, start)
                    if distance < min_result:
                        min_result = distance
                        best_row = mid + j
                        best_start = start
                        best_side = side
            else:  # Right side
                if right[mid + j - 1] >= size:
                    start = K - right[mid + j - 1] + 1
                    distance = calculate_distance(size, mid + j, mid, start)
                    if distance < min_result:
                        min_result = distance
                        best_row = mid + j
                        best_start = start
                        best_side = side

    return best_row, best_start, best_side

def assign_seats(N, K, requests):
    left, right, mid = initialize(K)
    results = []

    for size in requests:
        best_row, best_start, best_side = find_best_space(left, right, K, mid, size)
        if best_row == -1:
