def calc_lcp(s, sa):
    rank = [0 for _ in range(len(s))]
    for i in range(len(s)):
        rank[sa[i]] = i
    lcp = [0 for _ in range(len(s) - 1)]
    h = 0
    for i in range(len(s)):
        if rank[i] < len(s) - 1:
            while max(i, sa[rank[i] + 1]) + h < len(s) and s[i + h] == s[sa[rank[i] + 1] + h]:
                h += 1
            lcp[rank[i]] = h
            if h > 0:
                h -= 1
    return lcp, rank

def suffix_array(s):
    s += '\0'
    sa = [0 for _ in range(len(s))]

    cnt256 = [0 for _ in range(256)]
    for c in s:
        cnt256[ord(c)] += 1
    for i in range(1, 256):
        cnt256[i] += cnt256[i - 1]
    for i in range(len(s) - 1, -1, -1):
        cnt256[ord(s[i])] -= 1
        sa[cnt256[ord(s[i])]] = i

    rank = 0
    ranks = [0 for _ in range(len(s))]

    for i in range(1, len(s)):
        if s[sa[i - 1]] != s[sa[i]]:
            rank += 1
        ranks[sa[i]] = rank

    k = 1
    while k < len(s):
        sa_new = [0 for _ in range(len(s))]
        rank_new = [0 for _ in range(len(s))]

        for i in range(len(s)):
            sa_new[i] = sa[i] - k
            if sa_new[i] < 0:
                sa_new[i] += len(s)

        cnt = [0 for _ in range(len(s))]
        for i in range(len(s)):
            cnt[ranks[i]] += 1
        for i in range(1, len(s)):
            cnt[i] += cnt[i - 1]
        for i in range(len(s) - 1, -1, -1):
            cnt[ranks[sa_new[i]]] -= 1
            sa[cnt[ranks[sa_new[i]]]] = sa_new[i]

        rank = 0
        for i in range(1, len(s)):
            if ranks[sa[i - 1]] != ranks[sa[i]] or ranks[sa[i - 1] + k] != ranks[sa[i] + k]:
                rank += 1
            rank_new[sa[i]] = rank
        ranks = rank_new

        k *= 2

    return sa[1:]


def kmp(s, p):
    pi = [0 for _ in range(len(p))]
    k = 0
    for i in range(1, len(p)):
        while k > 0 and p[k] != p[i]:
            k = pi[k - 1]
        if p[k] == p[i]:
            k += 1
        pi[i] = k

    k = 0
    resp = []
    for i in range(len(s)):
        while k > 0 and p[k] != s[i]:
            k = pi[k - 1]
        if p[k] == s[i]:
            k += 1
        if k == len(p):
            resp.append(i - len(p) + 1)
            k = pi[k - 1]
    return resp


def lower_bound(list, value):
    left = 0
    right = len(list)
    while left < right:
        mid = int((left + right) / 2)
        if list[mid] < value:
            left = mid + 1
        else:
            right = mid
    return left


s = input()
start = input()
end = input()

indStart = kmp(s, start)
indEnd = kmp(s, end)

if len(indStart) == 0 or len(indEnd) == 0:
    print(0)

else:
	sa = suffix_array(s)
	lcp, rank = calc_lcp(s, sa)

	ind = rank[indStart[0]]
	for st in indStart:
		ind = min(ind, rank[st])

	resp = len(indEnd) - lower_bound(indEnd, sa[ind] + max(0, len(start) - len(end)))
