def suffix_array(s):
    n = len(s)
    sa = sorted(range(n), key=lambda i: s[i:])
    return sa

def lcp(s, sa):
    n = len(sa)
    rank = [0] * n
    for i, suffix in enumerate(sa):
        rank[suffix] = i
    lcp = [0] * (n - 1)
    h = 0
    for i in range(n):
        if rank[i] > 0:
            j = sa[rank[i] - 1]
            while i + h < n and j + h < n and s[i + h] == s[j + h]:
                h += 1
            lcp[rank[i] - 1] = h
            if h > 0:
                h -= 1
    return lcp

def binary_search(sa, s, pattern):
    left, right = 0, len(sa)
    while left < right:
        mid = (left + right) // 2
        if s[sa[mid]:].startswith(pattern):
            right = mid
        else:
            left = mid + 1
    return left

def count_distinct_substrings(s, start, end):
    sa = suffix_array(s)
    lcp = lcp(s, sa)

    start_idx = binary_search(sa, s, start)
    if start_idx == len(sa) or not s[sa[start_idx]:].startswith(start):
        return 0

    end_indices = []
    left = binary_search(sa, s, end)
    right = left
    while right < len(sa) and s[sa[right]:].startswith(end):
        end_indices.append(sa[right])
        right += 1

    count = 0
    for end_idx in end_indices:
        if end_idx < sa[start_idx] + len(start):
            continue
        count += 1
        i = start_idx + 1
        while i < len(sa) and lcp[i - 1] >= len(start):
            if sa[i] + len(start) <= end_idx:
                count += 1
            i += 1

    return count

s = input()
start = input()
end = input()

print(count_distinct_substrings(s, start, end))

