def elevator_arrival_times(n, m, participants):
    def find_elevator_time(si, ti):
        cycle_length = 2 * m - 2
        # Calculate the time when the elevator reaches floor si after or at time ti
        if si == 1:
            return max(ti, (ti // cycle_length) * cycle_length)
        elif si == m:
            return max(ti, (ti // cycle_length + 1) * cycle_length - m + 1)
        else:
            # Time to reach si going up
            up_time = (si - 1) + ((ti // cycle_length) * cycle_length)
            # Time to reach si going down
            down_time = (2 * m - si - 1) + ((ti // cycle_length + 1) * cycle_length - m + 1)
            return max(ti, min(up_time, down_time))

    results = []
    for si, fi, ti in participants:
        if si == fi:
            results.append(ti)
        else:
            # Find the time when the elevator reaches si
            elevator_si_time = find_elevator_time(si, ti)
            # Calculate the time to move from si to fi
            if si < fi:
                travel_time = fi - si
            else:
                travel_time = m - si + fi - 1
            results.append(elevator_si_time + travel_time)

    return results

