import math

def is_lucky_number(x):
    while x > 0:
        digit = x % 10
        if digit != 4 and digit != 7:
            return False
        x //= 10
    return True

def is_lucky_index(i):
    while i > 0:
        digit = i % 10
        if digit != 4 and digit != 7:
            return False
        i //= 10
    return True

def kth_permutation(n, k):
    if k > math.factorial(n):
        return -1

    k -= 1  # Convert to 0-based index
    numbers = list(range(1, n + 1))
    permutation = []

    for i in range(n, 0, -1):
        fact = math.factorial(i - 1)
        idx = k // fact
        permutation.append(numbers.pop(idx))
        k %= fact

    return permutation

