    # Determine the row number
    r = y // a + 1

    # Determine the number of squares in the row
    if r % 2 == 0:
        squares_in_row = 2
    else:
        squares_in_row = 1

    # Check if the point is within the row
    if r <= 0:
        return -1

    # Calculate the total number of squares in previous rows
    total_squares_before = 0
    for i in range(1, r):
        if i % 2 == 0:
            total_squares_before += 2
        else:
