def count_possible_positions(n, t, houses):
    valid_positions = set()

    for xi, ai in houses:
        # Calculate the left and right touch points
        left_touch = xi - ai / 2
        right_touch = xi + ai / 2

        # Calculate the range for the new house's center if touching the left edge
        left_min = left_touch - t / 2
        left_max = left_touch + t / 2

        # Calculate the range for the new house's center if touching the right edge
        right_min = right_touch - t / 2
        right_max = right_touch + t / 2

        # Function to check if a position overlaps with any existing house
        def is_overlapping(new_center):
            for xj, aj in houses:
                if abs(new_center - xj) < (aj / 2 + t / 2):
                    return True
            return False

        # Check all positions in the left range
        for pos in [left_min, left_max]:
            if not is_overlapping(pos):
                valid_positions.add(pos)

        # Check all positions in the right range
        for pos in [right_min, right_max]:
            if not is_overlapping(pos):
                valid_positions.add(pos)

