def count_cycles(n):
    if n == 2:
        return 10

    k = n // 2
    dp = [0] * (k + 1)
    dp[0] = 1

    for i in range(1, k + 1):
        dp[i] = (dp[i - 1] * 3) % MOD

    total_cycles = 0

    for i in range(1, k + 1):
        for j in range(1, k + 1):
            if i != j:
                total_cycles = (total_cycles + dp[i] * dp[j] * 2) % MOD
            else:
                total_cycles = (total_cycles + dp[i] * dp[j]) % MOD

    return total_cycles

