def count_palindrome_pairs(s):
    n = len(s)
    dp = [[False] * n for _ in range(n)]

    # Every single character is a palindrome
    for i in range(n):
        dp[i][i] = True

    # Fill the dp table
    for length in range(2, n + 1):  # length of the substring
        for i in range(n - length + 1):
            j = i + length - 1
            if length == 2:
                dp[i][j] = (s[i] == s[j])
            else:
                dp[i][j] = (s[i] == s[j]) and dp[i + 1][j - 1]

    # Prefix sum array to count palindromes ending before each position
    prefix_sum = [0] * (n + 1)
    for i in range(n):
        for j in range(i, n):
            if dp[i][j]:
                prefix_sum[j + 1] += 1
    for i in range(1, n + 1):
        prefix_sum[i] += prefix_sum[i - 1]

    # Count non-overlapping palindrome pairs
    count = 0
    for i in range(n):
        for j in range(i, n):
            if dp[i][j]:
                count += prefix_sum[n] - prefix_sum[j + 1]

    return count

# Read input
