def get_char(k):
    if k <= 26:
        return chr(ord('a') + k - 1)
    else:
        return chr(ord('0') + k - 27)

def get_substring(l, r, step):
    if step == 1:
        return 'a' * (r - l + 1)

    mid = (1 << (step - 2))  # Midpoint of the current step

    if r <= mid:
        return get_substring(l, r, step - 1)
    elif l > mid:
        return get_substring(l - mid - 1, r - mid - 1, step - 1)
    else:
        left_part = get_substring(l, mid, step - 1)
        right_part = get_substring(1, r - mid - 1, step - 1)
        return left_part + get_char(step) + right_part

def longest_common_substring(s1, s2):
    m, n = len(s1), len(s2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    max_length = 0

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
                max_length = max(max_length, dp[i][j])

    return max_length

