    dot_index = s.find('.')
    if dot_index == -1 or dot_index == 0 or dot_index >= len(s) - 1:
        return False
    name = s[:dot_index]
    ext = s[dot_index + 1:]
    return 1 <= len(name) <= 8 and 1 <= len(ext) <= 3

def split_into_filenames(s):
    n = len(s)
    dp = [False] * (n + 1)
    dp[0] = True
    prev = [-1] * (n + 1)

    for i in range(1, n + 1):
        for j in range(max(0, i - 12), i):
