            return [int(f"{d}{d}")]
        numbers = []
        for mid in range(10**(length-2)):
            mid_str = str(mid).zfill(length-2)
            num_str = f"{d}{mid_str}{d}"
            num = int(num_str)
            if l <= num <= r:
                numbers.append(num)
        return numbers

    count = 0

    # Count single-digit numbers
    for i in range(1, 10):
        if l <= i <= r:
            count += 1

    # Count multi-digit numbers
