def min_time_to_complete_game(n, computers, dependencies):
    # Step 1: Build the graph and in-degree array
    graph = [[] for _ in range(n)]
    in_degree = [0] * n

    for i in range(n):
        k = dependencies[i][0]
        for j in range(1, k + 1):
            u = dependencies[i][j] - 1
            graph[u].append(i)
            in_degree[i] += 1

    # Step 2: Topological sort using Kahn's algorithm
    topo_order = []
    queue = deque([i for i in range(n) if in_degree[i] == 0])

    while queue:
        u = queue.popleft()
        topo_order.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # Step 3: Dynamic Programming
    dp = [[float('inf')] * 4 for _ in range(n)]

    # Initialize dp for parts with no dependencies
    for i in range(n):
        if in_degree[i] == 0:
            dp[i][computers[i]] = 1

    # Time to switch between computers
    switch_time = {
        (1, 2): 1, (1, 3): 2,
        (2, 1): 2, (2, 3): 1,
        (3, 1): 1, (3, 2): 2
    }

    # Process each part in topological order
    for i in topo_order:
        for c in range(1, 4):
            if dp[i][c] == float('inf'):
                continue
            for v in graph[i]:
                for nc in range(1, 4):
                    if computers[v] == nc:
                        dp[v][nc] = min(dp[v][nc], dp[i][c] + 1 + (switch_time[(c, nc)] if c != nc else 0))

    # Find the minimum time to complete all parts
    result = float('inf')
    for i in range(n):
        for c in range(1, 4):
            result = min(result, dp[i][c])

    return result

