from collections import deque

def is_bipartite(graph, n):
    color = [-1] * (n + 1)
    for i in range(1, n + 1):
        if color[i] == -1:
            queue = deque([i])
            color[i] = 0
            while queue:
                u = queue.popleft()
                for v in graph[u]:
                    if color[v] == -1:
                        color[v] = 1 - color[u]
                        queue.append(v)
                    elif color[v] == color[u]:
                        return False
    return True

def min_students_to_remove(n, m, edges):
    graph = [[] for _ in range(n + 1)]
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    if is_bipartite(graph, n):
        return 0

    min_removals = n
    for i in range(1, n + 1):
        new_graph = [graph[j][:] for j in range(n + 1)]
        for j in range(len(new_graph[i])):
            new_graph[new_graph[i][j]].remove(i)
        new_graph[i] = []
        if is_bipartite(new_graph, n):
            min_removals = min(min_removals, 1)

    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            new_graph = [graph[k][:] for k in range(n + 1)]
            for l in range(len(new_graph[i])):
                if new_graph[i][l] == j:
