class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size))
        self.rank = [0] * size

    def find(self, u):
        if self.parent[u] != u:
            self.parent[u] = self.find(self.parent[u])
        return self.parent[u]

    def union(self, u, v):
        rootU = self.find(u)
        rootV = self.find(v)
        if rootU != rootV:
            if self.rank[rootU] > self.rank[rootV]:
                self.parent[rootV] = rootU
            elif self.rank[rootU] < self.rank[rootV]:
                self.parent[rootU] = rootV
            else:
                self.parent[rootV] = rootU
                self.rank[rootU] += 1

def min_additional_drifts(n, drifts):
    drift_map = {}
    index = 0
    for x, y in drifts:
        if (x, y) not in drift_map:
            drift_map[(x, y)] = index
            index += 1

    uf = UnionFind(index)

    for x, y in drifts:
        current_index = drift_map[(x, y)]
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            neighbor_x, neighbor_y = x + dx, y + dy
            if (neighbor_x, neighbor_y) in drift_map:
                neighbor_index = drift_map[(neighbor_x, neighbor_y)]
                uf.union(current_index, neighbor_index)

    root_set = set()
    for i in range(index):
        root_set.add(uf.find(i))

    return len(root_set) - 1

