def solve(n, m, v):
    if m < n - 1:
        return -1

    edges = []

    # Connect all nodes to v first
    for i in range(1, n + 1):
        if i != v:
            edges.append((v, i))

    # We have used n-1 edges so far
    current_edges = n - 1

    # Add additional edges to reach m edges
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if len(edges) == m:
                break
