def find_max_square_brackets(s):
    n = len(s)
    unmatched = [True] * n

    # First pass: left to right
    stack = []
    for i in range(n):
        if s[i] == '(':
            stack.append(i)
        elif s[i] == ')':
            if stack and s[stack[-1]] == '(':
                unmatched[stack.pop()] = False
                unmatched[i] = False
        elif s[i] == '[':
            stack.append(i)
        elif s[i] == ']':
            if stack and s[stack[-1]] == '[':
                unmatched[stack.pop()] = False
                unmatched[i] = False

    # Second pass: right to left
    stack = []
    for i in range(n-1, -1, -1):
        if s[i] == ')':
            stack.append(i)
        elif s[i] == '(':
            if stack and s[stack[-1]] == ')':
                unmatched[stack.pop()] = False
                unmatched[i] = False
        elif s[i] == ']':
            stack.append(i)
        elif s[i] == '[':
            if stack and s[stack[-1]] == ']':
                unmatched[stack.pop()] = False
                unmatched[i] = False

    # Identify the longest valid subsequence
    max_len = 0
    current_len = 0
    start_index = 0
    best_start = 0
    best_end = 0

    for i in range(n):
        if unmatched[i]:
            current_len = 0
        else:
            current_len += 1
            if current_len > max_len:
                max_len = current_len
                best_start = start_index
                best_end = i
        if unmatched[i]:
            start_index = i + 1

    # Count the number of '[' in the best subsequence
    best_subseq = s[best_start:best_end + 1]
    num_square_brackets = best_subseq.count('[')

    return num_square_brackets, best_subseq

