    n = len(s)
    max_length = 0

    for length in range(1, n):
        substring_count = {}

        for i in range(n - length + 1):
            substring = s[i:i+length]
            if substring in substring_count:
                substring_count[substring] += 1
            else:
                substring_count[substring] = 1

            if substring_count[substring] >= 2:
