def sieve_of_eratosthenes(limit):
    is_prime = [True] * (limit + 1)
    p = 2
    while (p * p <= limit):
        if (is_prime[p] == True):
            for i in range(p * p, limit + 1, p):
                is_prime[i] = False
        p += 1
    prime_numbers = [p for p in range(2, limit + 1) if is_prime[p]]
    return prime_numbers

def generate_prime_squares(primes):
    prime_squares = set()
    for prime in primes:
        prime_square = prime * prime
        if prime_square > 10**12:
            break
        prime_squares.add(prime_square)
    return prime_squares

