        negative_prefix_count[0] = 1
    for i in range(1, n):
        if temperatures[i] < 0:
            negative_prefix_count[i] = negative_prefix_count[i - 1] + 1
        else:
            negative_prefix_count[i] = negative_prefix_count[i - 1]

    # Count valid positive suffixes
    if temperatures[n - 1] > 0:
        positive_suffix_count[n - 1] = 1
    for i in range(n - 2, -1, -1):
        if temperatures[i] > 0:
            positive_suffix_count[i] = positive_suffix_count[i + 1] + 1
        else:
            positive_suffix_count[i] = positive_suffix_count[i + 1]

    # Determine the minimum number of changes required
    min_changes = float('inf')
    for k in range(n - 1):
        changes = (k + 1 - negative_prefix_count[k]) + (n - k - 1 - positive_suffix_count[k + 1])
        min_changes = min(min_changes, changes)

