def find_scc(n, edges):
    from collections import defaultdict, deque

    def dfs(u, stack, visited, graph):
        visited[u] = True
        for v in graph[u]:
            if not visited[v]:
                dfs(v, stack, visited, graph)
        stack.append(u)

    def dfs_reverse(u, scc, visited, reverse_graph):
        visited[u] = True
        scc.append(u)
        for v in reverse_graph[u]:
            if not visited[v]:
                dfs_reverse(v, scc, visited, reverse_graph)

    graph = defaultdict(list)
