def count_undoubtedly_lucky_numbers(n):
    n_str = str(n)
    length = len(n_str)

    def dp(pos, is_less, leading_zero, memo):
        if pos == length:
            return not leading_zero  # Count only if it's not just leading zeros

        if (pos, is_less, leading_zero) in memo:
            return memo[(pos, is_less, leading_zero)]

        count = 0
        for digit in range(10):
            if leading_zero and digit == 0:
                continue  # Skip leading zeros

            if is_less or digit < int(n_str[pos]):
                count += dp(pos + 1, True, False, memo)
            elif digit == int(n_str[pos]):
                count += dp(pos + 1, False, False, memo)

        memo[(pos, is_less, leading_zero)] = count
        return count

    total_count = 0
    for x in range(10):
        for y in range(10):
            if x == 0 and y == 0:
                continue  # Skip the case where both digits are zero
            memo = {}
            total_count += dp(0, False, True, memo)

    return total_count

