def count_undoubtedly_lucky_numbers(n):
    if n < 10:
        return n

    queue = deque(range(1, 10))
    count = 0

    while queue:
        num = queue.popleft()
        if num > n:
            continue
        count += 1
        digits = set(map(int, str(num)))
        if len(digits) == 1 or len(digits) == 2:
