def count_distinct_or_values(n, a):
    distinct_values = set()
    bit_count = [0] * 32

    def update_bit_count(bit_count, value, add=True):
        for i in range(32):
            if (value >> i) & 1:
                bit_count[i] += 1 if add else -1

    def compute_current_or(bit_count):
        current_or = 0
        for i in range(32):
            if bit_count[i] > 0:
                current_or |= (1 << i)
        return current_or

    for l in range(n):
        # Reset bit_count for the new starting point
        for i in range(32):
            bit_count[i] = 0

        for r in range(l, n):
            update_bit_count(bit_count, a[r], add=True)
            current_or = compute_current_or(bit_count)
            distinct_values.add(current_or)

    return len(distinct_values)

