def max_equal_elements(n, a):
    total_sum = sum(a)
    avg = total_sum / n

    # Potential target values
    target1 = int(avg)
    target2 = int(avg) + 1 if avg != int(avg) else target1

    def count_elements(target):
        excess = 0
        for num in a:
            if num > target:
                excess += num - target
            elif num < target:
                excess -= target - num
        return excess == 0

    count1 = sum(1 for num in a if num <= target1)
    count2 = sum(1 for num in a if num <= target2)

    if count_elements(target1):
        return count1
    elif count_elements(target2):
        return count2
    else:
        return min(count1, count2)

