def sieve_of_eratosthenes(n):
    is_prime = [True] * (n + 1)
    p = 2
    while (p * p <= n):
        if (is_prime[p] == True):
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
        p += 1
    prime_numbers = [p for p in range(2, n + 1) if is_prime[p]]
    return prime_numbers

def count_almost_primes(n):
    primes = sieve_of_eratosthenes(n)
    almost_prime_count = 0

    for num in range(2, n + 1):
        distinct_prime_divisors = set()
        for prime in primes:
            if prime > num:
                break
            if num % prime == 0:
                distinct_prime_divisors.add(prime)
        if len(distinct_prime_divisors) == 2:
            almost_prime_count += 1

    return almost_prime_count

# Read input
n = int(input().strip())

# Output the result
print(count_almost_primes(n))

