def smallest_integer_with_n_divisors(n):
    import math

    # Function to generate prime numbers up to a certain limit
    def generate_primes(limit):
        sieve = [True] * (limit + 1)
        sieve[0] = sieve[1] = False
        for start in range(2, int(math.sqrt(limit)) + 1):
            if sieve[start]:
                for multiple in range(start*start, limit + 1, start):
                    sieve[multiple] = False
        return [num for num, is_prime in enumerate(sieve) if is_prime]

    # Generate enough primes
    primes = generate_primes(100)  # More than enough for n <= 1000

    # Factorize n
    factors = []
    temp = n
    for prime in primes:
        count = 0
        while temp % prime == 0:
            temp //= prime
            count += 1
        if count > 0:
            factors.append(count)
        if temp == 1:
            break

    # If n is a prime number, the smallest number with n divisors is 2^(n-1)
    if len(factors) == 1:
        return 2**(n-1)

    # Sort factors in descending order to use smaller primes for larger exponents
    factors.sort(reverse=True)

    # Construct the smallest number with the given factors
    result = 1
    for i, exponent in enumerate(factors):
        result *= primes[i]**exponent

    return result

