def is_prime(num):
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def min_increments_to_prime(lst):
    total_increments = 0
    for num in lst:
        if not is_prime(num):
            # Find the next prime number greater than or equal to num
            next_prime = num
            while not is_prime(next_prime):
                next_prime += 1
            total_increments += (next_prime - num)
    return total_increments

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    m = int(input[1])
    matrix = []
    index = 2
    for _ in range(n):
        row = list(map(int, input[index:index + m]))
        matrix.append(row)
        index += m

    min_row_increments = float('inf')
    for row in matrix:
        min_row_increments = min(min_row_increments, min_increments_to_prime(row))

    min_col_increments = float('inf')
    for col in range(m):
        column = [matrix[row][col] for row in range(n)]
        min_col_increments = min(min_col_increments, min_increments_to_prime(column))

