def is_reachable(n, permutation, favorite_numbers):
    from collections import defaultdict, deque

    # Step 1: Build the graph
    graph = defaultdict(list)
    for i in range(n):
        for j in range(n):
            if abs(i - j) == favorite_numbers[i]:
                graph[i].append(j)
                graph[j].append(i)

    # Step 2: Find all connected components
    visited = [False] * n
    components = []

    def bfs(start):
        queue = deque([start])
        component = []
        while queue:
            node = queue.popleft()
            if not visited[node]:
                visited[node] = True
                component.append(node)
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        queue.append(neighbor)
        return component

    for i in range(n):
        if not visited[i]:
            components.append(bfs(i))

    # Step 3: Check permutations within each component
    for component in components:
        component_indices = sorted(component)
        component_values = [permutation[i] for i in component]
        expected_values = [i + 1 for i in component_indices]
        if sorted(component_values) != expected_values:
