def euler_totient(n):
    result = n
    p = 2
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1
    if n > 1:
        result -= result // n
    return result

def number_of_primitive_roots(p):
    return euler_totient(p - 1)

# Read input
p = int(input().strip())

# Output the number of primitive roots
print(number_of_primitive_roots(p))

