```python
def ip_to_int(ip):
    """Converts an IP address from dotted-decimal format to a 32-bit integer."""
    parts = map(int, ip.split('.'))
    return sum(part << (8 * (3 - i)) for i, part in enumerate(parts))

def int_to_ip(number):
    """Converts a 32-bit integer to an IP address in dotted-decimal format."""
    return '.'.join(str((number >> (8 * (3 - i))) & 0xFF) for i in range(4))

def find_subnet_mask(ips, k):
    """Finds the subnet mask that results in exactly k distinct network addresses."""
    ip_as_numbers = [ip_to_int(ip) for ip in ips]
    for i in range(32):
        mask = (1 << (32 - i)) - 1
        net_addresses = {mask & ip for ip in ip_as_numbers}
        if len(net_addresses) == k:
            return int_to_ip(mask)
    return '-1'

def main():
    n, k = map(int, input().split())
    ips = [input().strip() for _ in range(n)]
    print(find_subnet_mask(ips, k))

if __name__ == "__main__":
    main()
```

