def parse_coordinate(coord):
    col = ord(coord[0]) - ord('a')
    row = 8 - int(coord[1])
    return row, col

def find_shortest_path(start, end):
    start_row, start_col = parse_coordinate(start)
    end_row, end_col = parse_coordinate(end)

    moves = []
    while start_row != end_row or start_col != end_col:
        if start_row > end_row:
            if start_col > end_col:
                moves.append("LD")
                start_row -= 1
                start_col -= 1
            elif start_col < end_col:
                moves.append("RD")
                start_row -= 1
                start_col += 1
            else:
                moves.append("D")
                start_row -= 1
        elif start_row < end_row:
            if start_col > end_col:
                moves.append("LU")
                start_row += 1
                start_col -= 1
            elif start_col < end_col:
                moves.append("RU")
                start_row += 1
                start_col += 1
            else:
                moves.append("U")
                start_row += 1
        else:
            if start_col > end_col:
                moves.append("L")
                start_col -= 1
            else:
                moves.append("R")
                start_col += 1

    return len(moves), " ".join(moves)

