def get_attacked_by_rook(rook_pos, n):
    attacked = set()
    r, c = rook_pos
    for i in range(n):
        attacked.add((i, c))  # Same column
        attacked.add((r, i))  # Same row
    return attacked

def get_attacked_by_knight(knight_pos):
