    if 'a++' in summand:
        coeff = summand.replace('a++', '')
        return int(coeff) if coeff else 1, 'a++'
    elif '++a' in summand:
        coeff = summand.replace('++a', '')
        return int(coeff) if coeff else 1, '++a'
    else:
