def evaluate_expression(a, expression):
    summands = []
    i = 0
    while i < len(expression):
        if expression[i] == '+':
            i += 1
            continue
        elif expression[i] == '-':
            j = i + 1
            while j < len(expression) and expression[j].isdigit():
                j += 1
            if j < len(expression) and (expression[j] == 'a' or expression[j:j+3] == 'a++' or expression[j:j+3] == '++a'):
                summands.append('-' + expression[i:j+3])
                i = j + 3
            else:
                raise ValueError("Invalid expression")
        else:
            j = i
            while j < len(expression) and (expression[j].isdigit() or expression[j] == 'a'):
                j += 1
            summands.append(expression[i:j])
            i = j

    a_plus_plus = []
    plus_a_plus = []

    for summand in summands:
        coeff, op = parse_summand(summand)
        if op == 'a++':
            a_plus_plus.append(coeff)
        elif op == '++a':
            plus_a_plus.append(coeff)

    # Sort coefficients to maximize the result
    a_plus_plus.sort(reverse=True)
    plus_a_plus.sort(reverse=True)

    result = 0
    current_a = a

    for coeff in plus_a_plus:
        current_a += 1
        result += coeff * current_a

    for coeff in a_plus_plus:
        result += coeff * current_a
        current_a += 1

    return result

