def crack_safe(numbers):
    operations = []
    while True:
        if all(num == 1 for num in numbers):
            break

        found_operation = False
        for i in range(4):
            j = (i + 1) % 4
            if numbers[i] % 2 == 0 and numbers[j] % 2 == 0 and numbers[i] > 1 and numbers[j] > 1:
                numbers[i] //= 2
                numbers[j] //= 2
                operations.append(f"/{i+1}/{j+1}")
                found_operation = True
                break
            elif numbers[i] % 2 == 1 or numbers[j] % 2 == 1:
                numbers[i] += 1
                numbers[j] += 1
                operations.append(f"+{i+1}/{j+1}")
                found_operation = True
                break

        if not found_operation:
            return "-1"

        if len(operations) > 1000:
            return "-1"

    return "\n".join(operations)

