    if m % 2 == 0:
        for i in range(1, m):
            path.append((1, i))
        for i in range(1, n + 1):
            path.append((i, m))
        for i in range(m - 1, 0, -1):
            for j in range(n, 1, -1):
                if i % 2 == 1:
                    path.append((j, i))
                else:
                    path.append((n - j + 2, i))
