from collections import defaultdict, deque

def find_order(comparisons):
    graph = defaultdict(list)
    indegree = {coin: 0 for coin in 'ABC'}

    # Build the graph
    for comp in comparisons:
        lighter, heavier = comp[0], comp[2]
        graph[lighter].append(heavier)
        indegree[heavier] += 1

    # Topological sort using Kahn's algorithm
    queue = deque([coin for coin in indegree if indegree[coin] == 0])
    order = []

    while queue:
        if len(queue) > 1:
            return "Impossible"
        coin = queue.popleft()
        order.append(coin)
        for neighbor in graph[coin]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    if len(order) != 3:
        return "Impossible"

    return ''.join(order)

# Read input
