from itertools import permutations

def print_crossword(grid):
    for row in grid:
        print(''.join(row))

def is_valid_crossword(grid):
    # Check if the grid forms a valid crossword
    rows = len(grid)
    cols = len(grid[0])

    # Check the top-left corner
    if grid[0][0] != '.':
        return False

    # Check the bottom-right corner
    if grid[rows-1][cols-1] != '.':
        return False

    # Check the enclosed blank areas
    # There should be exactly two enclosed areas
    visited = [[False] * cols for _ in range(rows)]
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def dfs(x, y):
        stack = [(x, y)]
        while stack:
            cx, cy = stack.pop()
            if visited[cx][cy]:
                continue
            visited[cx][cy] = True
            for dx, dy in directions:
                nx, ny = cx + dx, cy + dy
                if 0 <= nx < rows and 0 <= ny < cols and not visited[nx][ny] and grid[nx][ny] == '.':
                    stack.append((nx, ny))

    # Find the first blank cell
    start_x, start_y = -1, -1
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == '.':
                start_x, start_y = i, j
                break
        if start_x != -1:
            break

    if start_x == -1:
        return False

    dfs(start_x, start_y)

    enclosed_count = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == '.' and not visited[i][j]:
                enclosed_count += 1
                dfs(i, j)

    return enclosed_count == 2

def construct_crossword(words):
    min_crossword = None

    for perm in permutations(words):
        # Try different configurations
        for orientation in [(0, 1), (1, 0)]:  # (vertical, horizontal)
            grid = [['.'] * 30 for _ in range(30)]

            # Place the first word
            if orientation == (0, 1):
                for i, c in enumerate(perm[0]):
                    grid[i][0] = c
            else:
                for i, c in enumerate(perm[0]):
                    grid[0][i] = c

            # Place the second word
            if orientation == (0, 1):
                for i, c in enumerate(perm[1]):
                    grid[i][len(perm[0])-1] = c
            else:
                for i, c in enumerate(perm[1]):
                    grid[len(perm[0])-1][i] = c

            # Place the third word
            if orientation == (0, 1):
                for i, c in enumerate(perm[2]):
                    grid[i][len(perm[0])+len(perm[1])-2] = c
            else:
                for i, c in enumerate(perm[2]):
                    grid[len(perm[0])+len(perm[1])-2][i] = c

            # Place the fourth word
            if orientation == (0, 1):
                for i, c in enumerate(perm[3]):
                    grid[i][len(perm[0])+len(perm[1])+len(perm[2])-3] = c
            else:
                for i, c in enumerate(perm[3]):
                    grid[len(perm[0])+len(perm[1])+len(perm[2])-3][i] = c

            # Place the fifth word
            if orientation == (0, 1):
                for i, c in enumerate(perm[4]):
                    grid[i][len(perm[0])+len(perm[1])+len(perm[2])+len(perm[3])-4] = c
            else:
                for i, c in enumerate(perm[4]):
                    grid[len(perm[0])+len(perm[1])+len(perm[2])+len(perm[3])-4][i] = c

            # Place the sixth word
            if orientation == (0, 1):
                for i, c in enumerate(perm[5]):
                    grid[i][len(perm[0])+len(perm[1])+len(perm[2])+len(perm[3])+len(perm[4])-5] = c
            else:
                for i, c in enumerate(perm[5]):
                    grid[len(perm[0])+len(perm[1])+len(perm[2])+len(perm[3])+len(perm[4])-5][i] = c

            if is_valid_crossword(grid):
                crossword_str = ''.join([''.join(row) for row in grid])
                if min_crossword is None or crossword_str < min_crossword:
                    min_crossword = crossword_str

    if min_crossword is None:
