def longest_regular_bracket_sequence(s):
    max_length = 0
    count_max_length = 0
    balance = 0
    last_invalid_index = -1

    for i, char in enumerate(s):
        if char == '(':
            balance += 1
        else:  # char == ')'
            balance -= 1

        if balance == 0:
            current_length = i - last_invalid_index
            if current_length > max_length:
                max_length = current_length
                count_max_length = 1
            elif current_length == max_length:
                count_max_length += 1
        elif balance < 0:
            last_invalid_index = i
            balance = 0

