def analyze_bhtml_tables(s):
    stack = []
    table_sizes = []
    i = 0
    n = len(s)

    while i < n:
        if s[i:i+7] == "<table>":
            stack.append(0)  # Start a new table
            i += 7
        elif s[i:i+5] == "<tr>":
            i += 5  # Start a new row
        elif s[i:i+5] == "<td>":
            if stack:
                stack[-1] += 1  # Increment cell count for the current table
            i += 5
            # Check if the cell contains another table
            if s[i:i+7] == "<table>":
                stack.append(0)  # Start a new nested table
        elif s[i:i+6] == "</td>":
            i += 6
            # Check if the cell contained a nested table
            if stack and s[i:i+7] == "<table>":
                nested_size = stack.pop()
                table_sizes.append(nested_size)
        elif s[i:i+6] == "</tr>":
            i += 6  # End of a row
        elif s[i:i+8] == "</table>":
            if stack:
                table_size = stack.pop()
                table_sizes.append(table_size)
            i += 8

    table_sizes.sort()
