def parse_path(path):
    parts = path.split('\\')
    disk, *folders, filename = parts[0][:-1], *parts[1:-1], parts[-1]
    return disk, folders, filename

def build_tree(paths):
    tree = {}
    for path in paths:
        disk, folders, filename = parse_path(path)
        current = tree.setdefault(disk, {})
        for folder in folders:
            current = current.setdefault(folder, {})
        current[filename] = None  # Mark as a file
    return tree

def count_subfolders_and_files(node):
    if not isinstance(node, dict):
        return 0, 0

    total_subfolders = 0
    total_files = 0

    for key, value in node.items():
        if isinstance(value, dict):
            subfolders, files = count_subfolders_and_files(value)
            total_subfolders += 1 + subfolders  # Count this subfolder and its subfolders
            total_files += files
        else:
            total_files += 1

    return total_subfolders, total_files

def find_max_values(tree):
    max_subfolders = 0
    max_files = 0

    def traverse(node):
        nonlocal max_subfolders, max_files
        if not isinstance(node, dict):
            return

        subfolders, files = count_subfolders_and_files(node)
        max_subfolders = max(max_subfolders, subfolders)
        max_files = max(max_files, files)

        for key, value in node.items():
            traverse(value)

    for disk, contents in tree.items():
        traverse(contents)

    return max_subfolders, max_files

