import re

def parse_macros(lines):
    macros = {}
    for line in lines:
        match = re.match(r'\s*#\s*define\s+(\w+)\s+(.+)', line)
        if match:
            name, value = match.groups()
            macros[name] = value.strip()
    return macros

def substitute(expression, macros, safe=False):
    def replace(match):
        name = match.group(1)
        value = macros[name]
        if safe:
            return f"({value})"
        return value
    pattern = r'\b(' + '|'.join(re.escape(name) for name in macros.keys()) + r')\b'
    return re.sub(pattern, replace, expression)

def remove_extra_parentheses(expression):
    stack = []
    result = []
    for char in expression:
        if char == '(':
            stack.append(len(result))
        elif char == ')':
            if stack and stack[-1] == len(result) - 1 and result[-1] == '(':
                stack.pop()
                result.pop()  # Remove '('
                continue
            stack.pop()
        result.append(char)
    return ''.join(result)

def normalize_expression(expression):
    return re.sub(r'\s+', '', expression)

def is_suspicious(macros, expression):
    standard_substituted = substitute(expression, macros)
    safe_substituted = substitute(expression, macros, safe=True)
    safe_simplified = remove_extra_parentheses(safe_substituted)
    return normalize_expression(standard_substituted) != normalize_expression(safe_simplified)

