def count_messages(n, text):
    import re
    # Split the text into sentences based on '.', '?', and '!'
    sentences = re.split(r'(?<=[.!?]) +', text)

    if not sentences[-1].endswith(('.', '?', '!')):
        return "Impossible"

    message_count = 0
    current_length = 0

    for sentence in sentences:
        stripped_sentence = sentence.strip()
        if len(stripped_sentence) > n:
            return "Impossible"

        if current_length + len(stripped_sentence) + (1 if current_length > 0 else 0) <= n:
            current_length += len(stripped_sentence) + (1 if current_length > 0 else 0)
        else:
            message_count += 1
            current_length = len(stripped_sentence)

    if current_length > 0:
        message_count += 1

