def gcd(x, y):
    while y != 0:
        x, y = y, x % y
    return x

def find_divisors(n):
    divisors = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
