        for i in range(n):
            for j in range(i+1, n):
                yield (pool[i], pool[j])

    ori = getPt()
    pts = []
    N = int(input())

    for _ in range(N):
        pts.append(getPt())

    vis = set([0])
    mint = [0]+[1e8]*(1<<N) # minimal time for dp
    pres = [None]*(1<<N) # previous step for reconstruct path
    allb = (1 << N)-1 # all objects contained state
