from fractions import Fraction

def expected_tosses(n):
    if n == 1:
        return Fraction(0, 1)

    # Count the number of times n can be divided by 2
    power_of_2 = 0
    while n % 2 == 0:
        n //= 2
        power_of_2 += 1

    if n == 1:
        return Fraction(power_of_2, 1)

    # Find the order of 2 modulo n
    t = 1
    order = 0
    while True:
        t = (t * 2) % n
        order += 1
        if t == 1:
            break

    # Calculate the expected number of tosses
    numerator = sum(i * (2 ** i) for i in range(order)) + order
    denominator = (2 ** order) - 1

    return Fraction(numerator, denominator) + Fraction(power_of_2, 1)

