def generate_password(n, k):
    # Step 1: Generate the initial sequence using the first k letters of the alphabet
    letters = 'abcdefghijklmnopqrstuvwxyz'
    initial_sequence = letters[:k] * (n // k + 1)

    # Step 2: Adjust the length to n
    password = list(initial_sequence[:n])

    # Step 3: Ensure no consecutive characters are the same
    for i in range(1, n):
        if password[i] == password[i - 1]:
            # Find a different character to replace the current one
            for candidate in letters[:k]:
                if candidate != password[i - 1]:
                    password[i] = candidate
                    break

    # Step 4: Return the final password
    return ''.join(password)

