import math
import sys

def read_input():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    points = [(int(input[2*i+1]), int(input[2*i+2])) for i in range(n)]
    return n, points

def vector(p1, p2):
    return (p2[0] - p1[0], p2[1] - p1[1])

def dot(v1, v2):
    return v1[0] * v2[0] + v1[1] * v2[1]

def norm(v):
    return math.sqrt(v[0]**2 + v[1]**2)

def unit_vector(v):
    n = norm(v)
    return (v[0] / n, v[1] / n)

def angle_between(v1, v2):
    cos_theta = dot(v1, v2) / (norm(v1) * norm(v2))
    return math.acos(cos_theta)

def bisector(v1, v2):
    u1 = unit_vector(v1)
    u2 = unit_vector(v2)
    return (u1[0] + u2[0], u1[1] + u2[1])

def project(v, u):
    return dot(v, u) / norm(u)

def main():
    n, points = read_input()
    min_distance = float('inf')

    for i in range(n):
        v1 = vector(points[i], points[(i+1) % n])
        v2 = vector(points[i], points[(i-1) % n])
        b = bisector(v1, v2)
        proj1 = project(v1, b)
        proj2 = project(v2, b)
        distance = abs(proj1 - proj2)
        min_distance = min(min_distance, distance)

    D = min_distance / 2
    print(f"{D:.10f}")

if __name__ == "__main__":
    main()

