    if b == 0:
        return a
    return gcd(b, a % b)

class Solution:
    def __init__(self, x=0, y=0):
        self.x = x
        self.y = y

def extended_gcd(a, b, sol):
    if a == 0:
        sol.x = 0
        sol.y = 1
        return b
    sol2 = Solution()
    d = extended_gcd(b % a, a, sol2)
    sol.x = sol2.y - (b // a) * sol2.x
    sol.y = sol2.x
    return d

def find_any_solution(a, b, c, sol):
    g = extended_gcd(abs(a), abs(b), sol)
    if c % g != 0:
