def min_colors(n):
    primes = sieve_of_eratosthenes(n + 1)
    colors = [0] * (n + 1)
    color_count = 0

    for i in range(2, n + 2):
        used_colors = set()
        for prime in primes:
            if i % prime == 0:
                multiple = i // prime
                while multiple <= n:
                    if colors[multiple] != 0:
                        used_colors.add(colors[multiple])
                    multiple += prime
        color = 1
        while color in used_colors:
            color += 1
        colors[i - 1] = color
        color_count = max(color_count, color)

