def bfs(n, concentrations):
    from collections import deque

    queue = deque([(0, 0)])  # (current_concentration, current_volume)
    visited = set()
    visited.add((0, 0))

    while queue:
        current_concentration, current_volume = queue.popleft()

        if current_volume > 0 and current_concentration * 1000 == n * current_volume:
            return current_volume

        for c in concentrations:
            new_concentration = current_concentration + c
            new_volume = current_volume + 1

            if (new_concentration, new_volume) not in visited:
                visited.add((new_concentration, new_volume))
                queue.append((new_concentration, new_volume))

    return -1

