from collections import deque

def can_reach_with_two_turns(grid):
    n = len(grid)
    m = len(grid[0])

    # Find start and end points
    start = None
    end = None
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'T':
                end = (i, j)

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # BFS queue: (x, y, current_direction_index, turn_count)
    queue = deque([(start[0], start[1], -1, 0)])
    visited = set()
    visited.add((start[0], start[1], -1))

    while queue:
        x, y, prev_dir, turns = queue.popleft()

        if (x, y) == end:
            return "YES"

        for i, (dx, dy) in enumerate(directions):
            nx, ny = x + dx, y + dy

            if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] != '*' and (nx, ny, i) not in visited:
                if prev_dir != -1 and (dx, dy) != directions[prev_dir]:
                    if turns < 2:
                        visited.add((nx, ny, i))
                        queue.append((nx, ny, i, turns + 1))
                else:
                    visited.add((nx, ny, i))
                    queue.append((nx, ny, i, turns))

    return "NO"

