def dfs(node, parent, depth, depths, tree):
    depths[node] = depth
    for neighbor in tree[node]:
        if neighbor != parent:
            dfs(neighbor, node, depth + 1, depths, tree)

def check_symmetry(a, b, c, d, depths):
    # Check if the number of offices between a and b is the same as between b and a
    # Similarly for c and d
    return abs(depths[a] - depths[b]) == abs(depths[c] - depths[d])

def main():
    import sys
    input = sys.stdin.read().split()

    n = int(input[0])
    a, b, c, d = map(int, input[1:5])
    parents = list(map(int, input[5:]))

    tree = [[] for _ in range(n + 1)]
    for i in range(1, n):
        tree[parents[i]].append(i + 1)
        tree[i + 1].append(parents[i])

    depths = [0] * (n + 1)
    dfs(1, -1, 0, depths, tree)

    if check_symmetry(a, b, c, d, depths):
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    main()

