    vowels = {'a', 'e', 'i', 'o', 'u', 'y'}
    result = []
    prev_char = ''
    count = 0

    for i in range(n):
        char = s[i]
        if char == prev_char:
            count += 1
        else:
            if prev_char in vowels:
                if prev_char in {'e', 'o'} and count == 1:
                    result.append(prev_char)
                elif count == 1 or prev_char not in {'e', 'o'}:
                    result.append(prev_char)
            prev_char = char
            count = 1

    # Handle the last character
    if prev_char in vowels:
        if prev_char in {'e', 'o'} and count == 1:
            result.append(prev_char)
        elif count == 1 or prev_char not in {'e', 'o'}:
            result.append(prev_char)
    else:
        result.append(prev_char)

    return ''.join(result)

