def min_extensions(a, b, h, w, n, extensions):
    if (h >= a and w >= b) or (h >= b and w >= a):
        return 0

    extensions.sort(reverse=True)

    def can_fit(h, w, a, b, n):
        for ext in extensions:
            if h >= a and w >= b:
                return True
            if h < a:
                h *= ext
            elif w < b:
                w *= ext
            n -= 1
            if n < 0:
                return False
        return h >= a and w >= b

    # Try doubling height first, then width
    if can_fit(h, w, a, b, n):
        return n - sum(1 for ext in extensions if h >= a and w >= b)

    # Try doubling width first, then height
    if can_fit(w, h, a, b, n):
        return n - sum(1 for ext in extensions if h >= a and w >= b)

