import sys
import math
from collections import Counter

def is_poisson(counter, p):
    total = sum(counter.values())
    mean = sum(k * count for k, count in counter.items()) / total + p
    variance = sum((k + p - mean) ** 2 * count for k, count in counter.items()) / total
    poisson_probabilities = {k: (mean ** k * math.exp(-mean)) / math.factorial(k) for k in range(max(counter.keys()) + 1 + p)}
    return all(abs(count / total - poisson_probabilities.get(k, 0)) < 0.01 for k, count in counter.items())

def is_uniform(counter, p):
    total = sum(counter.values())
    min_val = min(counter.keys()) + p
    max_val = max(counter.keys()) + p
    expected_count = total / (max_val - min_val + 1)
    return all(abs(count - expected_count) < 0.01 for count in counter.values())

