    if n < k:
        return -1

    # Function to check if we can form a sequence with GCD g
    def can_form_sequence(g):
        target_sum = n // g
        if target_sum < k * (k + 1) // 2:
            return False

        # Try to form the sequence
        sequence = []
        current_sum = 0
        for i in range(1, k + 1):
            next_num = i * g
            while next_num <= g * target_sum and (not sequence or next_num > sequence[-1]):
                sequence.append(next_num)
                current_sum += next_num
                break
            else:
                return False

        if current_sum == g * target_sum:
            return sequence
        return False

    # Iterate over possible GCDs from n down to 1
    for g in range(n, 0, -1):
        if n % g == 0:
            sequence = can_form_sequence(g)
            if sequence:
                return sequence

