import sys

def is_palindrome(time):
    return time == time[::-1]

def main():
    s = sys.stdin.readline().rstrip()
    h, m = map(int, s.split(':'))

    while True:
        m += 1
        if m == 60:
            m = 0
            h += 1
            if h == 24:
                h = 0
        time_str = f"{h:02}:{m:02}"
        if is_palindrome(time_str.replace(':', '')):
            break

    ih, im = map(int, s.split(':'))
    result = (h - ih) * 60 + (m - im)
    if result < 0:
        result += 24 * 60

    sys.stdout.write(str(result) + '\n')

main()

