def find_permutation(n, m, l):
    a = [0] * n

    for i in range(m):
        current_leader = l[i] - 1
        next_leader = l[(i + 1) % m] - 1

        # Calculate the difference to move from current_leader to next_leader
        diff = (next_leader - current_leader) % n

        if a[current_leader] == 0:
            a[current_leader] = diff + 1
        elif a[current_leader] != diff + 1:
            return -1

    # Check if all elements in a are non-zero
    if 0 in a:
        return -1

    return ' '.join(map(str, a))

