def is_good_lab(n, grid):
    row_sums = [set() for _ in range(n)]
    col_sums = [set() for _ in range(n)]

    # Precompute row sums
    for i in range(n):
        for j in range(n):
            for k in range(n):
                if j != k:
                    row_sums[i].add(grid[i][j] + grid[i][k])

    # Precompute column sums
    for j in range(n):
        for i in range(n):
            for k in range(n):
                if i != k:
                    col_sums[j].add(grid[i][j] + grid[k][j])

    # Check each element in the grid
    for i in range(n):
        for j in range(n):
            if grid[i][j] != 1 and grid[i][j] not in row_sums[i] and grid[i][j] not in col_sums[j]:
                return "No"

    return "Yes"

