#        d = (a + c - 2) // (c - 1)
#        yield d

def calc(d):
    return (d - 1) * len(a) - sum(i % d for i in a)

def ans1(D):
    for d in D:
        d -= 1
        if calc(d) <= k:
            return d
    return 1

def ans():
    for d, pd in zip(D, D[1:]):
        if time.time() > t:
            return anss
        d -= 1
        cd = calc(d)
        if cd <= k:
            return d
        if d == pd:
            continue
        cpd = calc(pd)
        if (d - pd) * (cd - cpd) >= ((cd - k) * (d - pd) + cd - cpd - 1):
            return d - ((cd - k) * (d - pd) + cd - cpd - 1) // (cd - cpd)
    return anss

