def find_special_icicles(n, x, y):
    # Step 1: Get XOR of all icicles
    xor_all = query(list(range(1, n + 1)))

    # Step 2: Identify a differing bit position
    diff_bit = xor_all & -xor_all  # Rightmost set bit

    # Step 3: Partition icicles based on the differing bit
    group1 = []
    group2 = []
    for i in range(1, n + 1):
        if query([i]) & diff_bit:
            group1.append(i)
        else:
            group2.append(i)

    # Step 4: Recursive search
    def find_pair(group):
        if len(group) == 2:
            return group
        mid = len(group) // 2
        xor_left = query(group[:mid])
        xor_right = query(group[mid:])
        if xor_left == xor_all:
            return find_pair(group[:mid])
        else:
            return find_pair(group[mid:])

    special_pair = find_pair(group1 if len(group1) > 1 else group2)

    # Step 5: Verify and output the result
    print(f"! {special_pair[0]} {special_pair[1]}", flush=True)

