import sys
sys.setrecursionlimit(10000)

MOD = 10**8

def solve():
    n1, n2, k1, k2 = map(int, input().split())

    from functools import lru_cache

    @lru_cache(None)
    def dp(f, h, last_type, last_count):
        # last_type: 0 for footman, 1 for horseman
        if f == 0 and h == 0:
            return 1

        total = 0
        if f > 0:
            if last_type == 0:
                if last_count < k1:
                    total += dp(f - 1, h, 0, last_count + 1)
            else:
                total += dp(f - 1, h, 0, 1)
        if h > 0:
            if last_type == 1:
                if last_count < k2:
                    total += dp(f, h - 1, 1, last_count + 1)
            else:
                total += dp(f, h - 1, 1, 1)

        return total % MOD

    result = 0
    if n1 > 0:
        result += dp(n1 - 1, n2, 0, 1)
    if n2 > 0:
        result += dp(n1, n2 - 1, 1, 1)

    print(result % MOD)

