def rotate(B):
    l = len(B[0])
    b = len(B)
    C = [[0 for _ in range(b)] for _ in range(l)]
    for p in range(l):
        for q in range(b):
            C[p][q] = B[q][l - 1 - p]
    return C

def cut(A, R, C, l, b):
    e = int(R / l)
    f = int(C / b)
    for i in range(e):
        for j in range(f):
            B = [[A[i * l + x][j * b + y] for y in range(b)] for x in range(l)]
            for k in range(4):
                g, h = len(B), len(B[0])
                for p in range(int(R / g)):
                    for q in range(int(C / h)):
