    block_positions = {}
    id_counter = 1
    output = []

    for _ in range(t):
        line = sys.stdin.readline()
        if not line:
            break
        parts = line.strip().split()
        if parts[0] == 'alloc':
            n = int(parts[1])
            pos = -1
            for i in range(m - n + 1):
                if all(memory[j] == 0 for j in range(i, i + n)):
                    pos = i
                    break
            if pos == -1:
                output.append("NULL")
            else:
                for j in range(pos, pos + n):
                    memory[j] = id_counter
                block_positions[id_counter] = (pos, n)
                output.append(str(id_counter))
                id_counter += 1
        elif parts[0] == 'erase':
            x = int(parts[1])
            if x not in block_positions:
                output.append("ILLEGAL_ERASE_ARGUMENT")
            else:
                pos, size = block_positions[x]
                for j in range(pos, pos + size):
                    memory[j] = 0
                del block_positions[x]
        elif parts[0] == 'defragment':
            new_block_positions = {}
            current_pos = 0
            for block_id in sorted(block_positions.keys()):
                size = block_positions[block_id][1]
                for j in range(current_pos, current_pos + size):
                    memory[j] = block_id
                new_block_positions[block_id] = (current_pos, size)
                current_pos += size
            block_positions.clear()
            for k, v in new_block_positions.items():
                block_positions[k] = v

