from collections import defaultdict

def main():
    import sys
    input = sys.stdin.read
    data = input().splitlines()

    n = int(data[0])
    papers = []
    for i in range(1, len(data)):
        parts = list(map(int, data[i].split()))
        papers.append(parts[1:])

    freq = defaultdict(int)
    for paper in papers:
        for num in set(paper):
            freq[num] += 1

    # Group numbers by their frequency
    grouped = defaultdict(list)
    for num, f in freq.items():
        grouped[f].append(num)

    # Reconstruct the sets
    sets_list = []
    while grouped[n - 1]:
        num = grouped[n - 1].pop()
        current_set = {num}
        queue = [num]

        while queue:
            val = queue.pop(0)
            for paper in papers:
                if val in paper:
                    for x in paper:
                        if x not in current_set:
                            current_set.add(x)
                            queue.append(x)
                            grouped[freq[x]].remove(x)
                            if freq[x] > 1:
                                grouped[freq[x] - 1].append(x)
        sets_list.append(sorted(current_set))

    for s in sets_list:
        print(len(s), *s)

