import sys

def main():
    n, m = list(map(int, sys.stdin.readline().split()))

    field = []

    for i in range(n):
        row = list(map(int, sys.stdin.readline().split()))
        field.append(row)

    nmoves = 0
    moves = []

    while True:
        minrow = [min(field[i][j] for j in range(m)) for i in range(n)]
        mincol = [min(field[i][j] for i in range(n)) for j in range(m)]
        maxrow, imaxrow = max((item, index) for index, item in enumerate(minrow))
        maxcol, imaxcol = max((item, index) for index, item in enumerate(mincol))
        if maxrow == maxcol == 0:
            break

        if (n >= m and maxcol > 0) or maxrow == 0:
            moves.append((maxcol, -(imaxcol + 1)))
            nmoves += maxcol
            for i in range(n):
                field[i][imaxcol] -= maxcol
        else:
            moves.append((maxrow, imaxrow + 1))
            nmoves += maxrow
            for j in range(m):
                field[imaxrow][j] -= maxrow

    maxelem = max(field[i][j] for i in range(n) for j in range(m))
    if maxelem > 0:
        sys.stdout.write('-1\n')
        return

    sys.stdout.write(str(nmoves) + '\n')
    for repeat, move in moves:
        for _ in range(repeat):
            mtype = 'row' if move > 0 else 'col'
            sys.stdout.write(mtype + ' ' + str(abs(move)) + '\n')

main()

