n, q, c = map(int, input().split())

stars = [list(map(int, input().split())) for _ in range(n)]
queries = [list(map(int, input().split())) for _ in range(q)]

# Initialize prefix sums for each time state (0 to c)
prefix = [[[0] * 101 for _ in range(101)] for _ in range(c + 1)]

for x, y, s in stars:
    for t in range(c + 1):
        brightness = (s + t) if (s + t) <= c else (s + t) - (c + 1)
        prefix[t][x][y] += brightness

# Build 2D prefix sums for each time state
for t in range(c + 1):
    for i in range(1, 101):
        for j in range(1, 101):
            prefix[t][i][j] += prefix[t][i-1][j] + prefix[t][i][j-1] - prefix[t][i-1][j-1]

# Process queries
for t, x1, y1, x2, y2 in queries:
    s = t % (c + 1)
    total = prefix[s][x2][y2] - prefix[s][x1-1][y2] - prefix[s][x2][y1-1] + prefix[s][x1-1][y1-1]
    print(total)
